def current_rows(events):
    latest = {}
    for event in events:
        id_ = event["id"]
        key = (event["event_time"], event["seq"])
        if id_ not in latest or key > latest[id_][0]:
            latest[id_] = (key, event["op"], event["value"])

    result = []
    for id_ in sorted(latest):
        _, op, value = latest[id_]
        if op != "D":
            result.append({"id": id_, "value": value})
    return result

import heapq

def stable_toposort(graph):
    nodes = list(graph)
    pos = {node: i for i, node in enumerate(nodes)}

    indegree = {node: 0 for node in nodes}
    dependents = {node: set() for node in nodes}

    for node, raw_deps in graph.items():
        deps = set(raw_deps)
        for dep in deps:
            if dep not in pos:
                raise ValueError(f"missing dependency: {dep!r}")
            indegree[node] += 1
            dependents[dep].add(node)

    ready = []
    for node in nodes:
        if indegree[node] == 0:
            heapq.heappush(ready, (pos[node], node))

    result = []
    while ready:
        _, node = heapq.heappop(ready)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, (pos[dependent], dependent))

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def schema_drift(expected, actual):
    issues = []

    def collect_leaves(node, prefix):
        for key, value in node.items():
            path = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                collect_leaves(value, path)
            else:
                issues.append(path)

    def walk(exp, act, prefix):
        for key in set(exp) | set(act):
            path = f"{prefix}.{key}" if prefix else key

            if key not in exp:
                collect_leaves(act[key], path)
            elif key not in act:
                collect_leaves(exp[key], path)
            else:
                exp_value = exp[key]
                act_value = act[key]
                exp_is_object = isinstance(exp_value, dict)
                act_is_object = isinstance(act_value, dict)

                if exp_is_object and act_is_object:
                    walk(exp_value, act_value, path)
                elif exp_is_object != act_is_object:
                    issues.append(path)
                elif exp_value != act_value:
                    issues.append(path)

    walk(expected, actual, "")
    return sorted(set(issues))

def bounded_batches(items, max_rows):
    if max_rows <= 0:
        raise ValueError("max_rows must be positive")

    batches = []
    current_batch = []
    current_rows = 0

    for partition, row_count in items:
        if row_count > max_rows:
            if current_batch:
                batches.append(current_batch)
                current_batch = []
                current_rows = 0
            batches.append([(partition, row_count)])
            continue

        if current_rows + row_count > max_rows:
            batches.append(current_batch)
            current_batch = []
            current_rows = 0

        current_batch.append((partition, row_count))
        current_rows += row_count

    if current_batch:
        batches.append(current_batch)

    return batches

def merge_payload_ranges(items):
    by_payload = {}
    for start, end, payload in items:
        if start > end:
            raise ValueError("start must not be greater than end")
        by_payload.setdefault(payload, []).append((start, end))

    result = []
    for payload, ranges in by_payload.items():
        ranges.sort()
        merged = []
        for start, end in ranges:
            if merged and start <= merged[-1][1]:
                if end > merged[-1][1]:
                    merged[-1][1] = end
            else:
                merged.append([start, end])
        for start, end in merged:
            result.append([start, end, payload])

    result.sort(key=lambda x: (x[0], x[1]))
    return result

